SHELL_HISTORY = "(()=>{'use strict';const nb=document.getElementById('notebook'),play=document.getElementById('play');if(!nb||!play)return;\n const h={owner:crypto.randomUUID(),screen:'home',route:'',depth:0,suppress:false};\n history.replaceState({npOwner:h.owner,npScreen:'home',npRoute:'',npDepth:0},'',location.href);\n function push(screen,key){h.screen=screen;h.route=key;h.depth++;history.pushState({npOwner:h.owner,npScreen:screen,npRoute:key,npDepth:h.depth},'',location.href)}\n play.addEventListener('click',()=>{if(h.screen!=='practice')push('practice',h.route)},true);\n document.getElementById('back').onclick=()=>{if(history.state?.npOwner===h.owner&&h.depth>0)history.back();else home()};\n window.addEventListener('popstate',event=>{const state=event.state;if(state?.npOwner!==h.owner)return;const previous=h.screen;h.depth=state.npDepth;h.screen=state.npScreen;h.route=state.npRoute||'';\n  if(h.screen==='home'){home();return}if(previous==='home'){play.onclick();return}h.suppress=true;try{if(typeof nb.contentWindow.appBack==='function')nb.contentWindow.appBack();else navigate('index.html#return')}catch{nb.contentWindow.postMessage({type:'nanpure-back'},'*')}\n });\n window.addEventListener('message',event=>{if(event.source!==nb.contentWindow||event.data?.type!=='np-notebook-route'||typeof event.data.key!=='string')return;const key=event.data.key;if(h.suppress){h.suppress=false;h.route=key;return}if(key===h.route)return;if(h.screen==='practice')push('practice',key);else h.route=key});\n})();\n"
